// GUARD: this workflow must never execute for another customer. No side effects here.
const input = $json || {};
const expectedSlug = 'clinica_nubia_oficial';
const expectedCapability = 'standard';
const expectedExtension = 'nubia';
if (String(input.tenant_slug || '') !== expectedSlug ||
    String(input.noria_extension || '') !== expectedExtension ||
    String(input.noria_contract_version || '') !== '1.0') {
  throw new Error('NORIA_EXTENSAO_TENANT_INCORRETO');
}
const uuid = String(input.tenant_id || '');
const instance = String(input.instance || '');
const chatId = String(input.remoteJid || '');
if (!/^[a-f0-9-]{36}$/i.test(uuid) || !instance || !chatId) throw new Error('NORIA_IDENTIDADE_INCOMPLETA');
const base = String($env.SUPABASE_URL || '').replace(/\/$/, '');
const key = String($env.SUPABASE_SERVICE_ROLE_KEY || '');
if (!base || !key) throw new Error('NORIA_CREDENCIAIS_SUPABASE_AUSENTES');
const headers = { apikey: key, Authorization: 'Bearer ' + key };
const get = endpoint => this.helpers.httpRequest({method:'GET', url:base+'/rest/v1/'+endpoint, headers, json:true, timeout:7000});
const tenants = await get('tenants?select=id,slug,status&id=eq.'+encodeURIComponent(uuid)+'&slug=eq.'+encodeURIComponent(expectedSlug)+'&limit=1');
if (!Array.isArray(tenants) || tenants.length !== 1 || tenants[0].status !== 'active') throw new Error('NORIA_TENANT_INVALIDO');
const settings = await get('tenant_settings?select=settings&tenant_id=eq.'+encodeURIComponent(uuid)+'&limit=1');
const s = settings?.[0]?.settings || {};
if (s.whatsapp_processing_mode !== 'conversation_core_v1') throw new Error('NORIA_MOTOR_INATIVO_TENANT');
const capability = s.conversation_capability === 'sales_v1' ? 'sales_v1' : 'standard';
if (capability !== expectedCapability) throw new Error('NORIA_CAPACIDADE_DIVERGENTE');
const channels = await get('channels?select=external_id,config,status&tenant_id=eq.'+encodeURIComponent(uuid)+'&type=eq.whatsapp&status=eq.active&limit=25');
if (!Array.isArray(channels) || !channels.some(c=>[c.external_id,c.config?.instance_name,c.config?.instance,c.config?.evolution_instance,c.config?.instance_id].filter(Boolean).includes(instance))) throw new Error('NORIA_INSTANCIA_NAO_PERTENCE_AO_TENANT');
// Reuse only sanitized configuration already fetched during tenant validation.
const verified = {
  tenant_id: uuid,
  whatsapp_processing_mode: s.whatsapp_processing_mode,
  conversation_capability: s.conversation_capability,
  whatsapp_audio_enabled: s.whatsapp_audio_enabled === true,
  appointment_scheduling: {enabled:s.appointment_scheduling?.enabled === true},
  approved_messages: {enabled:s.approved_messages?.enabled === true},
  business_facts: {service_guidance:s.business_facts?.service_guidance ? {spray:!!s.business_facts.service_guidance.spray} : null},
};
return {json:{...input,noria_verified_settings:verified}};

// No writes, AI calls, reservations, or outbound sends happen in extensions.
// This policy comes from the same tenant whose identity was validated upstream.
const input = $json || {};
const expectedSlug = "clinica_nubia_oficial";
if (input.tenant_slug !== expectedSlug || input.noria_extension !== "nubia") {
  throw new Error('NORIA_EXTENSION_POLICY_TENANT_MISMATCH');
}
const base = String($env.SUPABASE_URL || '').replace(/\/$/, '');
const key = String($env.SUPABASE_SERVICE_ROLE_KEY || '');
if (!base || !key) throw new Error('NORIA_EXTENSION_POLICY_NO_DB');
let rows=[];
if (input.noria_verified_settings?.tenant_id !== input.tenant_id) {
  rows = await this.helpers.httpRequest({
    method:'GET', url:base+'/rest/v1/tenant_settings?select=settings&tenant_id=eq.'
      + encodeURIComponent(input.tenant_id)+'&limit=1',
    headers:{apikey:key,Authorization:'Bearer '+key},json:true,timeout:7000,
  });
  if (!Array.isArray(rows)||rows.length!==1) throw new Error('NORIA_EXTENSION_POLICY_SETTINGS_MISSING');
}
const settings = (input.noria_verified_settings?.tenant_id === input.tenant_id
  ? input.noria_verified_settings : (rows[0].settings || {}));
const capability = settings.conversation_capability === 'sales_v1' ? 'sales_v1' : 'standard';
if (capability !== 'standard' || settings.whatsapp_processing_mode !== 'conversation_core_v1') {
  throw new Error('NORIA_EXTENSION_POLICY_SETTINGS_MISMATCH');
}
const profile = 'nb_bronze_v1';
const policy = {
  contract: 'noria_policy_v2', tenant_id: input.tenant_id, tenant_slug: expectedSlug,
  profile, capability,
  audio_enabled: settings.whatsapp_audio_enabled === true,
  scheduling_enabled: settings.appointment_scheduling?.enabled === true,
  modules: profile === 'nb_bronze_v1' ? {
    scheduling: settings.appointment_scheduling?.enabled === true,
    approved_service_texts: settings.approved_messages?.enabled === true,
    specific_service_guidance: !!settings.business_facts?.service_guidance,
    specific_service_id: 'bronze_jato_corpo_todo',
    messages: {
      home_booking: 'Sim, fazemos Bronze a Jato a domicílio. Vou chamar a equipe para verificar a região atendida, o valor e a disponibilidade antes de combinar o atendimento.',
      home_info: 'Sim! Também fazemos Bronze a Jato a domicílio. O valor, a região atendida e os horários disponíveis são confirmados pela nossa equipe.',
      clinic_prefix: 'Sim! Temos Bronze a Jato na clínica',
      clinic_home_note: ' Para atendimento em casa, a equipe confirma o valor e a disponibilidade.',
      home_schedule: 'Para atendimento a domicílio, a equipe confirma a região, o valor e os horários disponíveis. Vou chamar a equipe para verificar. [HUMANO_SOLICITADO]',
      spray_schedule: 'Para Bronze a Jato, os horários são confirmados pela equipe. Vou chamar alguém para verificar as opções para você. [HUMANO_SOLICITADO]',
    },
    payment_report_only: true, manual_signal_confirmation: true,
    deposit_source: 'tenant_settings',
  } : {
    qualification: true, vehicle_inventory: true,
    financing: true, appraisal: true,
    kanban_source: 'tenant_settings.sales.stage_keys',
    policies_source: 'tenant_settings.sales + tenant_settings.sdr_rules',
  },
};
return {json:{...input,noria_client_policy:policy}};
